package com.pharmapack.qms.deviation; import com.pharmapack.qms.batch.Batch; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="deviations") @Getter @Setter @NoArgsConstructor public class Deviation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="deviation_number",nullable=false,unique=true) String deviationNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id") Batch batch; String title; @Column(columnDefinition="TEXT") String description; String severity; String status="OPEN"; Long openedBy; LocalDateTime openedAt; LocalDateTime closedAt; }
